def solve(a, target):
    lo, hi = 0, len(a)
    while lo <= hi:
        mid = (lo + hi)//2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def solve(items):
    a=list(items)
    for i in range(1,len(a)):
        key=a[i]; j=i-1
        while j>=0 and a[j][0] >= key[0]:
            a[j+1]=a[j]; j-=1
        a[j+1]=key
    return a

def solve(graph, start):
    seen={start}; u=start
    while graph.get(u):
        u=graph[u][0]
        if u in seen: break
        seen.add(u)
    return sorted(seen)
